class Solution {
public:
    int longestOnes(vector<int>& a, int k) {
        int l = 0, zeros = 0, best = 0;
        for (int r = 0; r < (int)a.size(); r++) {
            if (a[r] == 0) zeros++;
            while (zeros > k) {
                if (a[l] == 0) zeros--;
                l++;
            }
            best = max(best, r - l + 1);
        }
        return best;
    }
};
