class Solution {
public:
    int longestSubarray(vector<int>& a) {
        int l = 0, zeros = 0, best = 0;
        for (int r = 0; r < (int)a.size(); r++) {
            zeros += (a[r] == 0);
            while (zeros > 1) zeros -= (a[l++] == 0);
            best = max(best, r - l);
        }
        return best;
    }
};
