class Solution {
public:
    int longestNiceSubarray(vector<int>& a) {
        int used = 0, l = 0, best = 0;
        for (int r = 0; r < (int)a.size(); r++) {
            while (used & a[r]) used ^= a[l++];
            used |= a[r];
            best = max(best, r - l + 1);
        }
        return best;
    }
};
