class Solution {
public:
    int numSubarrayProductLessThanK(vector<int>& a, int k) {
        if (k <= 1) return 0;
        long long prod = 1;
        int l = 0, cnt = 0;
        for (int r = 0; r < (int)a.size(); r++) {
            prod *= a[r];
            while (prod >= k) prod /= a[l++];
            cnt += r - l + 1;
        }
        return cnt;
    }
};
